import{_ as t,H as n,f as s,i}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"结束语 | 驾驭工程，让人的判断发挥更大价值","description":"","frontmatter":{},"headers":[],"relativePath":"Agent驾驭工程之美/结束语｜驾驭工程，让人的判断发挥更大价值.md","filePath":"Agent驾驭工程之美/结束语｜驾驭工程，让人的判断发挥更大价值.md","lastUpdated":1795453770000}'),a={name:"Agent驾驭工程之美/结束语｜驾驭工程，让人的判断发挥更大价值.md"};function p(A,e,E,r,g,o){return n(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="结束语-驾驭工程-让人的判断发挥更大价值" tabindex="-1">结束语 | 驾驭工程，让人的判断发挥更大价值 <a class="header-anchor" href="#结束语-驾驭工程-让人的判断发挥更大价值" aria-label="Permalink to &quot;结束语 | 驾驭工程，让人的判断发挥更大价值&quot;">​</a></h1><p>你好，我是徐昊，首先恭喜你完成了《驾驭工程之美》这门课程的学习，在 AI 时代，还要亲自学习，实属不易。大家辛苦了。</p><p>从课程一开始，就有两个经常被问到的问题，我始终没有来得及回答，今天借助结课的时机，来跟大家谈一谈。第一个是这门课程有没有代码库可以参考。第二个是这门课程能不能做成技能（Skill），让我们直接接入 Agent 来使用。这两个问题很有意思，我认为它们分别代表了两种不同的惰学习惯。也就是看起来在努力学习，其实都没学到点子上。</p><p>第一个问题对于学习的认知还停留在大模型之前的时代，学习的最终目标可能是想在工作中复用一些现成的成果。在过往的二十年里，代码的确具有很强的复用性，通过简单修改别人已经写好的代码，让它们适用到我们的工作中，很多时候是一种提高效率的可行手段。但并不是所有东西都可以通过代码承载，甚至对于很多知识，代码恰恰是最没有用的东西。</p><p>比如，对于重构而言，重构后的参考代码就是最没用的东西。因为重构所讲述的重点，是如何识别坏味道，以及如何通过对坏味道的修改，用好的设计模式来代替代码中的坏味道。这是一个过程比结果更重要的技能。重构的重点，从来不是那份改完的代码长什么样，而是你凭什么认定原代码里有坏味道、凭什么选这个设计模式来替换它。改完的代码扔进垃圾桶都没关系，因为下次你遇到的代码跟这次长得完全不一样。真正能带走的，是那份“认出坏味道、找到手法”的眼力和判断力。</p><p>如果我们不愿意去重视过程，提升自己的认知，而寄希望于参考一下最终结果，那么无论看起来多么努力地在学习，其实也是一种懒惰，最终也学不到什么东西。</p><p>而第二个问题，是能不能做一个技能（Skill）封装课程中的内容。这其实是第一个问题在大模型时代的升级。虽然代码变成了技能，背后的心理是同一个，想要一个现成的、封装好的成果，拿过来就能用，最好不用经历中间那个费劲的认知升级过程。</p><p>那么为什么无论是现成写好的 Harness，亦或是封装好的技能，对于 Harness Engineering 都没什么用呢？那是因为我们的课程讲解的核心内容，是如何构造一个 Agent 与人的交互模式，从而让人的判断力、认知能力达到最大的价值。</p><p>比如，在第一部分中，我们讲了操控循环，画出了这个交互模式的原型，也就是双层循环模型。外层 PDCA 负责把任务拆解成流程、追踪进度，内层操控循环负责每个子任务的质量控制和自我修正。内层循环包括四个环节，Guides（前馈）、Action（执行）、Sensors（反馈）、Steering（转向）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E9%A9%BE%E9%A9%AD%E5%B7%A5%E7%A8%8B%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E9%A9%BE%E9%A9%AD%E5%B7%A5%E7%A8%8B%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><p>人的位置是清清楚楚的，Guides 是人的，人在这里把意图、标准、约束给足；Steering 是人的，人在这里根据反馈做转向判断；Action 是 Agent 的，执行交给它；Sensors 尽量交给机器，能自动检查的就不用人盯着。这就是“让人的判断发挥最大价值”的第一层意思：人只出现在只有人能做的环节上，其余的都交出去。</p><p>我们的确可以通过一个技能，帮助我们搭建双层循环的结构，甚至我们都不用这么麻烦，拿一套双层循环的模版就好了，把 PDCA 以及操控循环空出来就好了。但是这套结构的重点，并不在于你有没有使用 PDCA 和操控循环，而是如何分割内外层循环的边界，再结合不同子系统的设计，让双层循环可以发挥最大的作用。整体的设计过程比结构更重要。</p><p>而到了第二部分，某种程度上说，我们教授的内容，更类似于 debug。Agent 让你失望，这是一个很模糊的信号，跟程序跑出错了差不多。debug 最难的地方从来不是怎么修，而是怎么知道问题出在哪。Agent 也一样，它让你失望，你得先搞清楚到底是哪出了问题：是需求没说清楚，是没建检查，是状态被弄脏了，还是环境变了…… 十三个坏味道，就是十三种常见的病因，帮你把“Agent 让我失望”这个模糊的感觉，落回到一个具体的环节上。</p><p>而且 debug 教会的，从来不是某一个 bug 怎么修，而是怎么从现象找到根因。这个能力是通用的，换项目、换语言都带得走。坏味道也一样，今天碰见的是模糊需求，明天碰见的是虚假胜利，症状不一样，但往回推、找到哪里断了，这个思路是一样的。诊断这件事，恰恰是人的判断力里最没法替代的部分。机器能帮你跑测试、报错，但把现象连成因果、判断根因在哪，还得靠人。debug 不好自动化，就是这个原因。第二部分教的，就是把这份能力用到人和Agent 的交互上。</p><p>所以这一部分也没有现成的东西能给你。你能带走的，是一套诊断的思路，Agent 让你失望的时候，先别急着怪模型，先问一句，是哪个环节断了。再去耐心寻找可能的解决方案。</p><p>我们始终要记得，驾驭工程是让人重新能够找到操控大模型的方法。而任何试图完全将人拿掉的尝试，都与这个出发点相违背。这也回答了一开始那两个问题为什么“问错了”。</p><p>要代码库、要现成的 Skill，深层都是同一个念头：想要一个“不用我操心”的东西，拿过来就能跑。但驾驭工程恰恰相反，它不是让你省掉操心，而是让你的操心更值钱。把判断外包出去，不是驾驭，是缴械。AI 时代，人不是被拿掉的，是被重新定义的。从“亲手做每一件事的执行者”，变成“决定该做什么、判断做得对不对的驾驭者”。驾驭工程教的，就是怎么当好这个驾驭者。这也正是这门课叫“驾驭”、而不是叫“自动化”的原因。</p><p>最后的最后，我还想提醒大家一点，在 AI 时代，人的判断力可能是最宝贵、最有价值的能力。让 AI 代替我们执行，而不是代替我们思考。与君共勉。</p><p>课程告一段落，希望你抽几分钟填一下结课问卷。期待能听到你的反馈，说说你对这门课程的想法和建议。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E9%A9%BE%E9%A9%AD%E5%B7%A5%E7%A8%8B%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E9%A9%BE%E9%A9%AD%E5%B7%A5%E7%A8%8B%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" alt=""></a></p>',20)])])}const l=t(a,[["render",p]]);export{B as __pageData,l as default};
